          '스위칭을 100&nbsp;ms 멈췄다가 소프트 스타트로 다시 시작한다. OVP2 위에서는 '
          '코어가 구동되는 일이 없으므로 OVP2 가 상한이고, 두 전압의 비가 여유의 '
