    add(p('<b>극성.</b> 그림의 극성점대로 감으면 레그 1 의 로우사이드 스위치가 '
          '켜진 동안 ZCD 전압이 양이 되어 요구 조건을 만족한다. NS2 와 NS3 는 같은 방향으로 '
          '감고, 탭은 NS2 의 끝과 NS3 의 시작을 잇는다. 표&nbsp;%s 의 값에서 다음 세 값을 구한다.' % TR('trafo-built')))
    add(p('<b>피크 자속 밀도</b>, f<sub>r</sub> 에서:'))
